#![no_std]
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]


use core::ffi::{c_char, c_int};
use core::fmt::{self, Write};

// Pull in the bindings generated by build.rs
include!("./bindings.rs");

pub struct LibcConsole;

impl Write for LibcConsole {
    fn write_str(&mut self, s: &str) -> fmt::Result {
        // "%.*s" requires two arguments: the length (int) and the string pointer (char*)
        // We append \0 to the format string itself so C knows where the format string ends.
        let format_str = "%.*s\0";

        unsafe {
            printf(
                format_str.as_ptr() as *const c_char,
                s.len() as c_int,
                s.as_ptr() as *const c_char,
            );
        }
        Ok(())
    }
}

